```python
from collections import deque

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_valid(s: str) -> bool:
        stack = deque()
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    def find_group(paren_string: str, level: int) -> List[str]:
        def dfs(i: int, s: str) -> None:
            if i == len(s):
                result.append(s)
                return

            if s[i] == '(':
                dfs(i+1, s[:i] + '(' + s[i+1:])
            elif s[i] == ')':
                if level > 1:
                    dfs(i+1, s[:i] + ')' + s[i+1:])
                else:
                    dfs(i+1, s[:i] + s[i+1:])

        dfs(0, paren_string)

    result = []
    level = 1
    for i, c in enumerate(paren_string):
        if c == '(':
            level += 1
        elif c == ')':
            if level > 1:
                level -= 1
            else:
                if is_valid(paren_string[:i]):
                    find_group(paren_string, level)
                    level = 1
    if level > 1:
        if is_valid(paren_string):
            find_group(paren_string, level)
    return result
```

