from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def _parse(s, level=0):
        if not s:
            return []
        result = []
        for c in s:
            if c == '(':
                _parse(s[1:], level + 1)
            elif c == ')':
                if level > 0:
                    _parse(s[1:], level - 1)
                result.append(level)
        return result

    return _parse(paren_string)

```

