from collections import deque

def correct_bracketing(brackets: str):
    pairs = {")": "(", "}": "{", "]": "[", ">": "<"}
    stack = deque()
    for bracket in brackets:
        if bracket in pairs:
            if not stack or stack.popleft() != pairs[bracket]:
                return False
        else:
            stack.append(bracket)
    return not stack
```

