 Here's the Python function that checks if a number is the product of three prime numbers, given that the number is less than 100. The function uses a helper function `is_prime()` to check if a number is prime.

```python
from math import sqrt

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def is_multiply_prime(a: int) -> bool:
    if a < 9 or a % 3 != 0:  # 3, 5, 7 are prime numbers
        return False
    factors = []
    while len(factors) < 3:
        for i in range(a, 1, -1):
            if a % i == 0:
                factors.append(i)
                a = a // i
                break
        else:
            return False  # if the number cannot be divided by any other number, it's not a product of 3 prime numbers
    return all(is_prime(f) for f in factors)
```

This code includes two functions:

1. `is_prime(n: int)`: Checks if a number is prime.
2. `is_multiply_prime(a: int)`: Checks if a number is the product of 3 prime numbers.

