def hex_key(num):
    hex_primes = {
        "2", "3", "5", "7", "B", "D", "11", "13", "17"
    }
    hex_to_decimal = {
        "A": 10, "B": 11, "C": 12, "D": 13, "E": 14, "F": 15
    }

