from typing import List

def next_smaller_index(arr, target):
    """Find the index of the next smaller element or -1 if not found."""
    for i, num in enumerate(arr):
        if num > target:
            break
        if arr[i + 1] < target:
            return i + 1
    return -1

def can_arrange(arr: List[int]):
    """Return the largest index of an element which is not greater than or equal to the element immediately preceding it. If no such element exists then return -1."""
    for i in range(len(arr) - 1, 0, -1):  # iterate from the end of the array to the beginning
        if arr[i] <= arr[i - 1] and next_smaller_index(arr[:i], arr[i]) != -1:
            return i
    return -1
```

